package com.slss.service;
import com.slss.domain.*; import com.slss.repository.*; import jakarta.transaction.Transactional; import org.springframework.stereotype.Service; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import org.springframework.security.core.context.SecurityContextHolder; import java.time.*;
@Service public class RepairOrderService {
 private final RepairOrderRepository repo; private final OrderStatusHistoryRepository history; private final AssetRepository assets; private final LifecycleEventRepository lifecycle; private final RepairPartRepository parts; private final AssetComponentRepository components; private final AuditService audit; private final TenantScopeService tenantScope;
 public RepairOrderService(RepairOrderRepository repo,OrderStatusHistoryRepository history,AssetRepository assets, LifecycleEventRepository lifecycle,RepairPartRepository parts,AssetComponentRepository components,AuditService audit,TenantScopeService tenantScope){this.repo=repo;this.history=history;this.assets=assets;this.lifecycle=lifecycle;this.parts=parts;this.components=components;this.audit=audit;this.tenantScope=tenantScope;}
 public OrderStatus getCurrentStatus(Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在")).getStatus();}
 @Transactional public RepairOrder create(RepairOrder order){var saved=repo.save(order);recordHistory(saved,null,saved.getStatus(),"工单创建");recordLifecycle(saved,"SERVICE_ORDER_CREATED","售后工单 "+saved.getOrderNumber()+" 已创建");return saved;}
 @Transactional public RepairOrder update(Long id,String customerName,String faultDescription,String machineSn,String receivedConfigJson,String actualFaultDescription){var order=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在"));tenantScope.requireAccess(order.getTenant());if(customerName!=null)order.setCustomerName(customerName);if(faultDescription!=null)order.setFaultDescription(faultDescription);if(actualFaultDescription!=null)order.setActualFaultDescription(actualFaultDescription);if(receivedConfigJson!=null)order.setReceivedConfigJson(receivedConfigJson);if(machineSn!=null&&!machineSn.equals(order.getMachineSn())){assets.findByMachineSnIgnoreCase(machineSn).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"整机 SN 不存在："+machineSn));order.setMachineSn(machineSn);}var saved=repo.save(order);var auth=SecurityContextHolder.getContext().getAuthentication();audit.record(auth==null?"system":auth.getName(),"ORDER_UPDATE","REPAIR_ORDER",String.valueOf(saved.getId()),"更新工单 "+saved.getOrderNumber(),null,true);return saved;}
 @Transactional public RepairOrder assign(Long id,Long userId,Duration sla,String reason){var order=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在"));if(userId==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"负责人不能为空");if(sla==null||sla.isZero()||sla.isNegative())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"SLA 时长必须大于 0");if(order.getAssignedTo()!=null&&!order.getAssignedTo().equals(userId)&&(reason==null||reason.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"转派工单必须填写原因");order.setAssignedTo(userId);order.setSlaDueAt(Instant.now().plus(sla));order.setSlaPausedAt(null);order.setSlaRemainingSeconds(null);return repo.save(order);}
 @Transactional public RepairOrder extendSla(Long id,Duration extension,String reason){var order=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在"));if(extension==null||extension.isZero()||extension.isNegative())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"延期时长必须大于 0");if(reason==null||reason.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"SLA 延期必须填写原因");if(order.getStatus()==OrderStatus.CLOSED||order.getStatus()==OrderStatus.CANCELLED)throw new ResponseStatusException(HttpStatus.CONFLICT,"终态工单不能延期");if(order.getStatus()==OrderStatus.SUSPENDED){long remaining=order.getSlaRemainingSeconds()==null?0:order.getSlaRemainingSeconds();order.setSlaRemainingSeconds(remaining+extension.toSeconds());}else{Instant base=order.getSlaDueAt()==null?Instant.now():order.getSlaDueAt();order.setSlaDueAt(base.plus(extension));}recordLifecycle(order,"SLA_EXTENDED","SLA 延期 "+extension.toHours()+" 小时："+reason);return repo.save(order);}
 @Transactional public RepairOrder transition(Long id, OrderStatus target, String reason){ var order=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在"));var from=order.getStatus();if(target==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"目标状态不能为空");if((target==OrderStatus.SUSPENDED||target==OrderStatus.CANCELLED)&& (reason==null||reason.isBlank()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"挂起或取消必须填写原因");if(target==OrderStatus.ASSIGNED&&order.getAssignedTo()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"工单必须先分配负责人");if(target==OrderStatus.CLOSED&&order.getSlaDueAt()==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"工单缺少 SLA 截止时间");if(!OrderWorkflow.canTransition(from,target)) throw new ResponseStatusException(HttpStatus.CONFLICT,"非法状态转移: "+from+" -> "+target);if(target==OrderStatus.SUSPENDED){Instant now=Instant.now();order.setSlaRemainingSeconds(order.getSlaDueAt()==null?null:Math.max(0,Duration.between(now,order.getSlaDueAt()).toSeconds()));order.setSlaPausedAt(now);}else if(from==OrderStatus.SUSPENDED){long remaining=order.getSlaRemainingSeconds()==null?0:order.getSlaRemainingSeconds();order.setSlaDueAt(Instant.now().plusSeconds(remaining));order.setSlaPausedAt(null);order.setSlaRemainingSeconds(null);}order.setStatus(target);var saved=repo.save(order);recordHistory(saved,from,target,reason);recordLifecycle(saved,"SERVICE_STATUS_CHANGED",from+" -> "+target+(reason==null?"":"："+reason));return saved;}
 @Transactional public RepairPart replacePart(Long orderId,String partName,String oldSn,String newSn){var order=repo.findById(orderId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"工单不存在"));tenantScope.requireAccess(order.getTenant());if(newSn==null||newSn.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"新组件 SN 不能为空");var asset=order.getMachineSn()==null?null:assets.findByMachineSnIgnoreCase(order.getMachineSn()).orElse(null);if(components.existsBySerialNo(newSn))throw new ResponseStatusException(HttpStatus.CONFLICT,"新组件 SN 已存在");
  if(asset!=null&&oldSn!=null&&!oldSn.isBlank()){
   // Only remove the old serial from the work order's asset. Never delete a
   // same-number component belonging to another asset.
   components.findByAssetIdAndSerialNoIgnoreCase(asset.getId(),oldSn.trim()).ifPresent(components::delete);
  }
  if(asset!=null){var c=new AssetComponent();c.setAsset(asset);c.setComponentType(partName);c.setModel(partName);c.setSerialNo(newSn.trim());components.save(c);var e=new LifecycleEvent();e.setAsset(asset);e.setEventType("REPAIR_SWAP");e.setPartName(partName);e.setOldSn(oldSn);e.setNewSn(newSn);e.setDetails("售后工单 "+order.getOrderNumber()+" 更换组件");lifecycle.save(e);}var p=new RepairPart();p.setOrder(order);p.setPartName(partName);p.setOldSn(oldSn);p.setNewSn(newSn);return parts.save(p);}
 private void recordHistory(RepairOrder order,OrderStatus from,OrderStatus to,String reason){var h=new OrderStatusHistory();h.setOrder(order);h.setFromStatus(from);h.setToStatus(to);h.setReason(reason);var auth=SecurityContextHolder.getContext().getAuthentication();h.setOperatedBy(auth==null?"system":auth.getName());history.save(h);}
 private void recordLifecycle(RepairOrder order,String type,String details){if(order.getMachineSn()==null)return;assets.findByMachineSnIgnoreCase(order.getMachineSn()).ifPresent(a->{var e=new LifecycleEvent();e.setAsset(a);e.setEventType(type);e.setDetails(details);lifecycle.save(e);});}
}
